-- Seeds the 3 solar-inverter TOU presets referenced by the customer
-- dashboard's Time-of-Use tab: selecting one writes its whole values set
-- through the same device_settings pipeline as any individual field edit,
-- tagged with applied_preset_key (see 20260924000100's device_settings
-- columns). Generated by gen_tou_presets.mjs, not hand-typed.

insert into waytara.setting_presets (key, name, description, device_category, values)
values
  ('tou_solar_self_use', 'Solar Self-Use', 'The battery only ever charges from your own solar production, never from the grid. Maximizes savings by avoiding grid-charging costs entirely, at the cost of a lower reserve on low-sun days.', 'solar_inverter', '{"tou_slot1_start_time":"0","tou_slot1_power_w":0,"tou_slot1_target_soc_pct":100,"tou_slot1_target_voltage_v":55,"tou_slot1_flags":4,"tou_slot2_start_time":"400","tou_slot2_power_w":0,"tou_slot2_target_soc_pct":100,"tou_slot2_target_voltage_v":55,"tou_slot2_flags":4,"tou_slot3_start_time":"800","tou_slot3_power_w":0,"tou_slot3_target_soc_pct":100,"tou_slot3_target_voltage_v":55,"tou_slot3_flags":4,"tou_slot4_start_time":"1200","tou_slot4_power_w":0,"tou_slot4_target_soc_pct":100,"tou_slot4_target_voltage_v":55,"tou_slot4_flags":4,"tou_slot5_start_time":"1600","tou_slot5_power_w":0,"tou_slot5_target_soc_pct":100,"tou_slot5_target_voltage_v":55,"tou_slot5_flags":4,"tou_slot6_start_time":"2000","tou_slot6_power_w":0,"tou_slot6_target_soc_pct":100,"tou_slot6_target_voltage_v":55,"tou_slot6_flags":4}'::jsonb),
  ('tou_off_peak_topup', 'Off-Peak Top-Up', 'Solar-only the rest of the day, but tops the battery up from the grid during the cheapest overnight hours (00:00-04:00) so you start each morning at full charge. A small grid-cost trade-off for a more reliable morning reserve.', 'solar_inverter', '{"tou_slot1_start_time":"0","tou_slot1_power_w":4000,"tou_slot1_target_soc_pct":100,"tou_slot1_target_voltage_v":55,"tou_slot1_flags":5,"tou_slot2_start_time":"400","tou_slot2_power_w":0,"tou_slot2_target_soc_pct":100,"tou_slot2_target_voltage_v":55,"tou_slot2_flags":4,"tou_slot3_start_time":"800","tou_slot3_power_w":0,"tou_slot3_target_soc_pct":100,"tou_slot3_target_voltage_v":55,"tou_slot3_flags":4,"tou_slot4_start_time":"1200","tou_slot4_power_w":0,"tou_slot4_target_soc_pct":100,"tou_slot4_target_voltage_v":55,"tou_slot4_flags":4,"tou_slot5_start_time":"1600","tou_slot5_power_w":0,"tou_slot5_target_soc_pct":100,"tou_slot5_target_voltage_v":55,"tou_slot5_flags":4,"tou_slot6_start_time":"2000","tou_slot6_power_w":0,"tou_slot6_target_soc_pct":100,"tou_slot6_target_voltage_v":55,"tou_slot6_flags":4}'::jsonb),
  ('tou_backup_priority', 'Backup Priority', 'Tops the battery up from the grid twice a day — overnight (00:00-04:00) and in the evening (20:00-00:00) — to keep it near full through both the morning and evening peak-demand windows. Uses more grid power than the other templates, in exchange for the strongest outage backup.', 'solar_inverter', '{"tou_slot1_start_time":"0","tou_slot1_power_w":4000,"tou_slot1_target_soc_pct":100,"tou_slot1_target_voltage_v":55,"tou_slot1_flags":5,"tou_slot2_start_time":"400","tou_slot2_power_w":0,"tou_slot2_target_soc_pct":100,"tou_slot2_target_voltage_v":55,"tou_slot2_flags":4,"tou_slot3_start_time":"800","tou_slot3_power_w":0,"tou_slot3_target_soc_pct":100,"tou_slot3_target_voltage_v":55,"tou_slot3_flags":4,"tou_slot4_start_time":"1200","tou_slot4_power_w":0,"tou_slot4_target_soc_pct":100,"tou_slot4_target_voltage_v":55,"tou_slot4_flags":4,"tou_slot5_start_time":"1600","tou_slot5_power_w":0,"tou_slot5_target_soc_pct":100,"tou_slot5_target_voltage_v":55,"tou_slot5_flags":4,"tou_slot6_start_time":"2000","tou_slot6_power_w":4000,"tou_slot6_target_soc_pct":100,"tou_slot6_target_voltage_v":55,"tou_slot6_flags":5}'::jsonb)
